INSERT INTO challenges (id, title, instructions, category, type, difficulty, concepts, spec, legacy)
VALUES
  ('a11y-formulario-etiquetas-01', 'Formulario de contacto sin etiquetas', 'La auditoría marca los campos sin nombre accesible. Asocia una <label> visible a cada campo (for + id), incluido el <select>. Mantén los tres campos y el botón.', 'accesibilidad', 'challenge', 'junior', ARRAY['a11y-formularios']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-formulario-etiquetas-01","title":"Formulario de contacto sin etiquetas","difficulty":"junior","concepts":["a11y-formularios"],"instructions":"La auditoría marca los campos sin nombre accesible. Asocia una <label> visible a cada campo (for + id), incluido el <select>. Mantén los tres campos y el botón.","files":{"index.html":"<main>\n  <h1>Contacto</h1>\n  <form>\n    <input id=\"nombre\" type=\"text\" placeholder=\"Nombre\">\n    <input id=\"email\" type=\"email\" placeholder=\"Email\">\n    <select id=\"motivo\">\n      <option>Soporte</option>\n      <option>Ventas</option>\n    </select>\n    <button type=\"submit\">Enviar</button>\n  </form>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\nlabel { display: block; margin-top: 8px; }","app.js":""},"tests":[{"name":"Todos los campos tienen nombre accesible","type":"dom","code":"const v = await audit([\"label\",\"select-name\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Las etiquetas son visibles (no solo aria-label)","type":"dom","code":"return ['nombre', 'email', 'motivo'].every((id) => { const l = $('label[for=' + id + ']'); return l && l.textContent.trim().length > 1 && rect(l).height > 0; }) || 'Cada campo necesita <label for> visible.';"},{"name":"El formulario conserva sus campos","type":"dom","code":"return $$('form input').length === 2 && !!$('form select') && !!$('form button');"}],"hints":["<label for=\"email\">Email</label> se asocia al input con id=\"email\".","El <select> también necesita su etiqueta."],"solution":{"index.html":"<main>\n  <h1>Contacto</h1>\n  <form>\n    <label for=\"nombre\">Nombre</label>\n    <input id=\"nombre\" type=\"text\" placeholder=\"Nombre\">\n    <label for=\"email\">Email</label>\n    <input id=\"email\" type=\"email\" placeholder=\"Email\">\n    <label for=\"motivo\">Motivo</label>\n    <select id=\"motivo\">\n      <option>Soporte</option>\n      <option>Ventas</option>\n    </select>\n    <button type=\"submit\">Enviar</button>\n  </form>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-imagenes-alt-01', 'Galería con imágenes sin texto alternativo', 'Añade alt a todas las imágenes. El logo y las fotos informativas necesitan una descripción; el separador decorativo debe llevar alt vacío (alt="") para que el lector lo ignore.', 'accesibilidad', 'challenge', 'junior', ARRAY['a11y-imagenes']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-imagenes-alt-01","title":"Galería con imágenes sin texto alternativo","difficulty":"junior","concepts":["a11y-imagenes"],"instructions":"Añade alt a todas las imágenes. El logo y las fotos informativas necesitan una descripción; el separador decorativo debe llevar alt vacío (alt=\"\") para que el lector lo ignore.","files":{"index.html":"<header><img id=\"logo\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"40\" height=\"40\"> Viajes Norte</header>\n<main>\n  <h1>Destinos</h1>\n  <figure><img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"200\" height=\"120\"><figcaption>Bilbao</figcaption></figure>\n  <img id=\"separador\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"300\" height=\"4\">\n  <figure><img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"200\" height=\"120\"><figcaption>San Sebastián</figcaption></figure>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; }","app.js":""},"tests":[{"name":"Ninguna imagen sin alt","type":"dom","code":"const v = await audit([\"image-alt\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"El logo y las fotos se describen","type":"dom","code":"return [$('#logo'), ...$$('.foto')].every((i) => (i.getAttribute('alt') || '').trim().length >= 3) || 'Describe el logo y cada foto.';"},{"name":"El separador es decorativo","type":"dom","code":"return $('#separador').getAttribute('alt') === '' || 'El separador debe tener alt=\"\".';"}],"hints":["alt describe lo que aporta la imagen, no «imagen de…».","Una imagen decorativa lleva alt=\"\" (vacío), no se quita el atributo."],"solution":{"index.html":"<header><img id=\"logo\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"40\" height=\"40\" alt=\"Viajes Norte, inicio\"> Viajes Norte</header>\n<main>\n  <h1>Destinos</h1>\n  <figure><img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"200\" height=\"120\" alt=\"Ría de Bilbao con el Guggenheim al fondo\"><figcaption>Bilbao</figcaption></figure>\n  <img id=\"separador\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"300\" height=\"4\" alt=\"\">\n  <figure><img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"200\" height=\"120\" alt=\"Playa de La Concha al atardecer\"><figcaption>San Sebastián</figcaption></figure>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-botones-icono-01', 'Botones de icono sin nombre', 'Los botones del reproductor solo tienen un icono SVG y el lector anuncia «botón». Dales un nombre accesible (aria-label o texto oculto) y marca los SVG como decorativos (aria-hidden="true").', 'accesibilidad', 'challenge', 'junior', ARRAY['a11y-semantica']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-botones-icono-01","title":"Botones de icono sin nombre","difficulty":"junior","concepts":["a11y-semantica"],"instructions":"Los botones del reproductor solo tienen un icono SVG y el lector anuncia «botón». Dales un nombre accesible (aria-label o texto oculto) y marca los SVG como decorativos (aria-hidden=\"true\").","files":{"index.html":"<main>\n  <h1>Podcast</h1>\n  <div class=\"controles\">\n    <button id=\"anterior\"><svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path d=\"M6 6h2v12H6zm3.5 6 8.5 6V6z\"/></svg></button>\n    <button id=\"play\"><svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path d=\"M8 5v14l11-7z\"/></svg></button>\n    <button id=\"siguiente\"><svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path d=\"M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z\"/></svg></button>\n  </div>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; }\nbutton { width: 44px; height: 44px; }","app.js":""},"tests":[{"name":"Todos los botones tienen nombre","type":"dom","code":"const v = await audit([\"button-name\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Los nombres describen la acción","type":"dom","code":"const n = (b) => (b.getAttribute('aria-label') || b.textContent || '').trim().toLowerCase(); return /anterior/.test(n($('#anterior'))) && /(reproducir|play)/.test(n($('#play'))) && /siguiente/.test(n($('#siguiente'))) || 'Usa nombres como «Anterior», «Reproducir», «Siguiente».';"},{"name":"Los iconos son decorativos","type":"dom","code":"return $$('button svg').every((s) => s.getAttribute('aria-hidden') === 'true');"}],"hints":["<button aria-label=\"Reproducir\">…</button>","Añade aria-hidden=\"true\" a cada <svg>."],"solution":{"index.html":"<main>\n  <h1>Podcast</h1>\n  <div class=\"controles\">\n    <button id=\"anterior\" aria-label=\"Anterior\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path d=\"M6 6h2v12H6zm3.5 6 8.5 6V6z\"/></svg></button>\n    <button id=\"play\" aria-label=\"Reproducir\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path d=\"M8 5v14l11-7z\"/></svg></button>\n    <button id=\"siguiente\" aria-label=\"Siguiente\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" width=\"24\" height=\"24\"><path d=\"M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z\"/></svg></button>\n  </div>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-contraste-01', 'Texto gris que no se lee', 'La auditoría de contraste falla en la tarjeta de precios: el texto secundario y el botón no llegan a 4,5:1. Cambia solo los colores en styles.css hasta que pase, sin tocar los tamaños.', 'accesibilidad', 'challenge', 'semi_senior', ARRAY['a11y-contraste']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["styles.css"],"id":"a11y-contraste-01","title":"Texto gris que no se lee","difficulty":"semi_senior","concepts":["a11y-contraste"],"instructions":"La auditoría de contraste falla en la tarjeta de precios: el texto secundario y el botón no llegan a 4,5:1. Cambia solo los colores en styles.css hasta que pase, sin tocar los tamaños.","files":{"index.html":"<main>\n  <h1>Plan Pro</h1>\n  <article class=\"tarjeta\">\n    <p class=\"precio\">9 € / mes</p>\n    <p class=\"nota\">Cancela cuando quieras. IVA incluido.</p>\n    <a class=\"boton\" href=\"#\">Suscribirme</a>\n  </article>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; background: #ffffff; color: #1f2328; }\n.tarjeta { padding: 16px; border: 1px solid #d0d7de; border-radius: 12px; max-width: 320px; }\n.precio { font-size: 1.5rem; font-weight: 700; }\n.nota { color: #a0a7b0; font-size: 0.9rem; }\n.boton { display: inline-block; padding: 10px 16px; border-radius: 8px; background: #7aa2ff; color: #ffffff; text-decoration: none; }","app.js":""},"tests":[{"name":"Contraste AA en toda la página","type":"dom","code":"const v = await audit([\"color-contrast\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Los tamaños no cambian","type":"dom","code":"return style('.nota', 'font-size') === '14.4px' && style('.precio', 'font-size') === '24px';"}],"hints":["El gris #a0a7b0 sobre blanco da ~2,5:1; prueba algo como #57606a.","El botón: oscurece el fondo azul (p. ej. #2f5bd3) manteniendo el texto blanco."],"solution":{"styles.css":"body { font-family: system-ui, sans-serif; background: #ffffff; color: #1f2328; }\n.tarjeta { padding: 16px; border: 1px solid #d0d7de; border-radius: 12px; max-width: 320px; }\n.precio { font-size: 1.5rem; font-weight: 700; }\n.nota { color: #57606a; font-size: 0.9rem; }\n.boton { display: inline-block; padding: 10px 16px; border-radius: 8px; background: #2f5bd3; color: #ffffff; text-decoration: none; }"}}$webwiz5$::jsonb, false),
  ('a11y-enlaces-nombre-01', 'Enlaces que no dicen adónde van', 'Hay un enlace que solo contiene una imagen sin alt y un enlace-icono vacío. Haz que todos los enlaces tengan un nombre que indique su destino, y cambia el «aquí» por un texto descriptivo.', 'accesibilidad', 'challenge', 'junior', ARRAY['a11y-semantica']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-enlaces-nombre-01","title":"Enlaces que no dicen adónde van","difficulty":"junior","concepts":["a11y-semantica"],"instructions":"Hay un enlace que solo contiene una imagen sin alt y un enlace-icono vacío. Haz que todos los enlaces tengan un nombre que indique su destino, y cambia el «aquí» por un texto descriptivo.","files":{"index.html":"<main>\n  <h1>Ayuda</h1>\n  <p>Para descargar la factura pulsa <a id=\"aqui\" href=\"/facturas\">aquí</a>.</p>\n  <a id=\"perfil\" href=\"/perfil\"><img src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"32\" height=\"32\"></a>\n  <a id=\"twitter\" href=\"https://x.com/webwiz\" class=\"icono\"><span class=\"ico\"></span></a>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; }\n.ico { display: inline-block; width: 24px; height: 24px; background: #1f2328; border-radius: 50%; }","app.js":""},"tests":[{"name":"Todos los enlaces tienen nombre","type":"dom","code":"const v = await audit([\"link-name\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"El enlace de facturas es descriptivo","type":"dom","code":"const t = $('#aqui').textContent.trim().toLowerCase(); return (t !== 'aquí' && /factura/.test(t)) || 'Cambia «aquí» por, por ejemplo, «descargar la factura».';"},{"name":"Los destinos no cambian","type":"dom","code":"return $('#aqui').getAttribute('href') === '/facturas' && $('#perfil').getAttribute('href') === '/perfil' && $('#twitter').getAttribute('href').includes('x.com');"}],"hints":["Una imagen dentro de un enlace necesita alt con el destino: alt=\"Mi perfil\".","Para el icono vacío, aria-label en el <a>."],"solution":{"index.html":"<main>\n  <h1>Ayuda</h1>\n  <p>Puedes <a id=\"aqui\" href=\"/facturas\">descargar la factura</a> desde tu cuenta.</p>\n  <a id=\"perfil\" href=\"/perfil\"><img src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" width=\"32\" height=\"32\" alt=\"Mi perfil\"></a>\n  <a id=\"twitter\" href=\"https://x.com/webwiz\" class=\"icono\" aria-label=\"WebWiz en X\"><span class=\"ico\" aria-hidden=\"true\"></span></a>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-estructura-01', 'Página sin estructura: encabezados y regiones', 'La página salta de <h1> a <h4> y no tiene región principal, así que el contenido queda fuera de cualquier landmark. Añade <main> (y <header>/<footer> si quieres) y corrige el orden de los encabezados sin cambiar los textos.', 'accesibilidad', 'challenge', 'semi_senior', ARRAY['a11y-semantica']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-estructura-01","title":"Página sin estructura: encabezados y regiones","difficulty":"semi_senior","concepts":["a11y-semantica"],"instructions":"La página salta de <h1> a <h4> y no tiene región principal, así que el contenido queda fuera de cualquier landmark. Añade <main> (y <header>/<footer> si quieres) y corrige el orden de los encabezados sin cambiar los textos.","files":{"index.html":"<div class=\"cabecera\"><h1>Recetas</h1></div>\n<div class=\"contenido\">\n  <h4>Tortilla de patatas</h4>\n  <p>Huevos, patatas y paciencia.</p>\n  <h4>Marmitako</h4>\n  <p>Bonito, patata y pimiento choricero.</p>\n</div>\n<div class=\"pie\">© Recetas del norte</div>","styles.css":"body { font-family: system-ui, sans-serif; }\nh4 { font-size: 1.25rem; }","app.js":""},"tests":[{"name":"Hay una región principal y todo está en regiones","type":"dom","code":"const v = await audit([\"landmark-one-main\",\"region\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Los encabezados no se saltan niveles","type":"dom","code":"const v = await audit([\"heading-order\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Se conservan las dos recetas","type":"dom","code":"return /Tortilla/.test(document.body.textContent) && /Marmitako/.test(document.body.textContent) && $$('h1').length === 1;"}],"hints":["Tras un h1 vienen h2: cambia los h4 por h2 (el tamaño se ajusta con CSS).","Envuelve las recetas en <main>, la cabecera en <header> y el pie en <footer>."],"solution":{"index.html":"<header class=\"cabecera\"><h1>Recetas</h1></header>\n<main class=\"contenido\">\n  <h2>Tortilla de patatas</h2>\n  <p>Huevos, patatas y paciencia.</p>\n  <h2>Marmitako</h2>\n  <p>Bonito, patata y pimiento choricero.</p>\n</main>\n<footer class=\"pie\">© Recetas del norte</footer>"}}$webwiz5$::jsonb, false),
  ('a11y-foco-01', 'El orden del tabulador está roto', 'Alguien puso tabindex positivos para «ordenar» el foco y un aria-hidden en un bloque que contiene un enlace enfocable. Elimina los tabindex positivos y evita que haya elementos ocultos al lector que reciban el foco.', 'accesibilidad', 'challenge', 'semi_senior', ARRAY['a11y-semantica']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-foco-01","title":"El orden del tabulador está roto","difficulty":"semi_senior","concepts":["a11y-semantica"],"instructions":"Alguien puso tabindex positivos para «ordenar» el foco y un aria-hidden en un bloque que contiene un enlace enfocable. Elimina los tabindex positivos y evita que haya elementos ocultos al lector que reciban el foco.","files":{"index.html":"<main>\n  <h1>Pedido</h1>\n  <label for=\"cp\">Código postal</label>\n  <input id=\"cp\" tabindex=\"3\">\n  <label for=\"ciudad\">Ciudad</label>\n  <input id=\"ciudad\" tabindex=\"1\">\n  <button tabindex=\"2\">Calcular envío</button>\n  <div class=\"promo\" aria-hidden=\"true\">\n    <p>¡Envío gratis desde 50 €!</p>\n    <a href=\"/condiciones\">Condiciones</a>\n  </div>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; }","app.js":""},"tests":[{"name":"Sin tabindex positivos","type":"dom","code":"const v = await audit([\"tabindex\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Nada oculto al lector recibe el foco","type":"dom","code":"const v = await audit([\"aria-hidden-focus\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Los campos y el enlace siguen ahí","type":"dom","code":"return !!$('#cp') && !!$('#ciudad') && !!$('a[href=\"/condiciones\"]');"}],"hints":["El orden del foco debe seguir el del DOM: quita los tabindex (o pon 0).","Si la promo es útil, no la ocultes con aria-hidden; si es decorativa, saca el enlace."],"solution":{"index.html":"<main>\n  <h1>Pedido</h1>\n  <label for=\"cp\">Código postal</label>\n  <input id=\"cp\">\n  <label for=\"ciudad\">Ciudad</label>\n  <input id=\"ciudad\">\n  <button>Calcular envío</button>\n  <div class=\"promo\">\n    <p>¡Envío gratis desde 50 €!</p>\n    <a href=\"/condiciones\">Condiciones</a>\n  </div>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-aria-valida-01', 'Pestañas con ARIA mal escrito', 'El componente de pestañas usa role="tab" sin un contenedor role="tablist" y valores ARIA inválidos (aria-selected="si"). Corrige el marcado ARIA para que la auditoría pase.', 'accesibilidad', 'challenge', 'senior', ARRAY['a11y-semantica']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-aria-valida-01","title":"Pestañas con ARIA mal escrito","difficulty":"senior","concepts":["a11y-semantica"],"instructions":"El componente de pestañas usa role=\"tab\" sin un contenedor role=\"tablist\" y valores ARIA inválidos (aria-selected=\"si\"). Corrige el marcado ARIA para que la auditoría pase.","files":{"index.html":"<main>\n  <h1>Ajustes</h1>\n  <div class=\"pestanas\">\n    <button role=\"tab\" id=\"t1\" aria-selected=\"si\" aria-controls=\"p1\">Perfil</button>\n    <button role=\"tab\" id=\"t2\" aria-selected=\"no\" aria-controls=\"p2\">Seguridad</button>\n  </div>\n  <section id=\"p1\" role=\"tabpanel\" aria-labelledby=\"t1\">Datos del perfil</section>\n  <section id=\"p2\" role=\"tabpanel\" aria-labelledby=\"t2\" hidden>Contraseña y 2FA</section>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; }","app.js":""},"tests":[{"name":"Valores ARIA válidos","type":"dom","code":"const v = await audit([\"aria-valid-attr-value\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Las pestañas están dentro de un tablist","type":"dom","code":"const v = await audit([\"aria-required-parent\",\"aria-required-children\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"La primera pestaña sigue seleccionada","type":"dom","code":"return $('#t1').getAttribute('aria-selected') === 'true' && $('#t2').getAttribute('aria-selected') === 'false';"}],"hints":["aria-selected solo admite \"true\" o \"false\".","El contenedor de las pestañas necesita role=\"tablist\" (y un aria-label)."],"solution":{"index.html":"<main>\n  <h1>Ajustes</h1>\n  <div class=\"pestanas\" role=\"tablist\" aria-label=\"Ajustes\">\n    <button role=\"tab\" id=\"t1\" aria-selected=\"true\" aria-controls=\"p1\">Perfil</button>\n    <button role=\"tab\" id=\"t2\" aria-selected=\"false\" aria-controls=\"p2\">Seguridad</button>\n  </div>\n  <section id=\"p1\" role=\"tabpanel\" aria-labelledby=\"t1\">Datos del perfil</section>\n  <section id=\"p2\" role=\"tabpanel\" aria-labelledby=\"t2\" hidden>Contraseña y 2FA</section>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-listas-01', 'Listas que no son listas', 'El menú tiene <div> directamente dentro de <ul> y unos <li> sueltos fuera de cualquier lista. Corrige la estructura para que el lector anuncie «lista, 3 elementos».', 'accesibilidad', 'challenge', 'junior', ARRAY['a11y-semantica']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-listas-01","title":"Listas que no son listas","difficulty":"junior","concepts":["a11y-semantica"],"instructions":"El menú tiene <div> directamente dentro de <ul> y unos <li> sueltos fuera de cualquier lista. Corrige la estructura para que el lector anuncie «lista, 3 elementos».","files":{"index.html":"<main>\n  <h1>Menú del día</h1>\n  <ul class=\"platos\">\n    <div>Ensalada</div>\n    <div>Lentejas</div>\n    <div>Flan</div>\n  </ul>\n  <h2>Alérgenos</h2>\n  <li>Gluten</li>\n  <li>Huevo</li>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; }","app.js":""},"tests":[{"name":"Las listas solo contienen <li>","type":"dom","code":"const v = await audit([\"list\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Ningún <li> fuera de una lista","type":"dom","code":"const v = await audit([\"listitem\"]); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Los platos y alérgenos siguen","type":"dom","code":"return $$('.platos > li').length === 3 && $$('li').length === 5;"}],"hints":["Cambia los <div> del menú por <li>.","Envuelve los alérgenos en un <ul>."],"solution":{"index.html":"<main>\n  <h1>Menú del día</h1>\n  <ul class=\"platos\">\n    <li>Ensalada</li>\n    <li>Lentejas</li>\n    <li>Flan</li>\n  </ul>\n  <h2>Alérgenos</h2>\n  <ul>\n    <li>Gluten</li>\n    <li>Huevo</li>\n  </ul>\n</main>"}}$webwiz5$::jsonb, false),
  ('a11y-formulario-avanzado-01', 'Auditoría completa del formulario de registro', 'Haz que el formulario de registro pase la auditoría WCAG A/AA completa: hay un enlace dentro de un botón, ids duplicados referenciados por ARIA y un autocomplete inválido. Mantén los campos y el botón de enviar.', 'accesibilidad', 'challenge', 'senior', ARRAY['a11y-formularios']::TEXT[], $webwiz5${"category":"accesibilidad","run":{"axe":true},"editable":["index.html"],"id":"a11y-formulario-avanzado-01","title":"Auditoría completa del formulario de registro","difficulty":"senior","concepts":["a11y-formularios"],"instructions":"Haz que el formulario de registro pase la auditoría WCAG A/AA completa: hay un enlace dentro de un botón, ids duplicados referenciados por ARIA y un autocomplete inválido. Mantén los campos y el botón de enviar.","files":{"index.html":"<main>\n  <h1>Crea tu cuenta</h1>\n  <form>\n    <label for=\"correo\">Email</label>\n    <input id=\"correo\" type=\"email\" autocomplete=\"correo-electronico\" aria-describedby=\"ayuda\">\n    <p id=\"ayuda\">Te enviaremos un enlace de confirmación.</p>\n    <label for=\"clave\">Contraseña</label>\n    <input id=\"clave\" type=\"password\" autocomplete=\"new-password\" aria-describedby=\"ayuda\">\n    <p id=\"ayuda\">Mínimo 12 caracteres.</p>\n    <button type=\"submit\">Crear cuenta <a href=\"/terminos\">y aceptar términos</a></button>\n  </form>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; color: #1f2328; }\nlabel, input { display: block; }","app.js":""},"tests":[{"name":"Auditoría WCAG A/AA sin errores","type":"dom","code":"const v = await audit(); return v.length === 0 || ('La auditoría falla: ' + v.map((x) => x.help + ' (' + x.nodes + ')').join('; '));"},{"name":"Los campos conservan su ayuda","type":"dom","code":"const a = $('#correo').getAttribute('aria-describedby'), b = $('#clave').getAttribute('aria-describedby'); return !!a && !!b && a !== b && !!document.getElementById(a) && !!document.getElementById(b);"},{"name":"El enlace de términos sigue en la página","type":"dom","code":"return !!$('a[href=\"/terminos\"]') && !$('button a') && !!$('button[type=submit]');"}],"hints":["Cada ayuda necesita su propio id (ayuda-email, ayuda-clave).","autocomplete=\"email\" es el valor válido; saca el enlace del botón."],"solution":{"index.html":"<main>\n  <h1>Crea tu cuenta</h1>\n  <form>\n    <label for=\"correo\">Email</label>\n    <input id=\"correo\" type=\"email\" autocomplete=\"email\" aria-describedby=\"ayuda-email\">\n    <p id=\"ayuda-email\">Te enviaremos un enlace de confirmación.</p>\n    <label for=\"clave\">Contraseña</label>\n    <input id=\"clave\" type=\"password\" autocomplete=\"new-password\" aria-describedby=\"ayuda-clave\">\n    <p id=\"ayuda-clave\">Mínimo 12 caracteres.</p>\n    <p>Al crear la cuenta aceptas los <a href=\"/terminos\">términos</a>.</p>\n    <button type=\"submit\">Crear cuenta</button>\n  </form>\n</main>"}}$webwiz5$::jsonb, false),
  ('seg-xss-comentarios-01', 'Comentarios que ejecutan código', '1) Explota: publica el comentario <img src=x onerror="window.__pwned=true;document.body.style.background=''red''"> en la vista previa. 2) Parchea app.js para que los comentarios se muestren siempre como texto.', 'seguridad', 'challenge', 'junior', ARRAY['xss']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-xss-comentarios-01","title":"Comentarios que ejecutan código","difficulty":"junior","concepts":["xss"],"instructions":"1) Explota: publica el comentario <img src=x onerror=\"window.__pwned=true;document.body.style.background='red'\"> en la vista previa. 2) Parchea app.js para que los comentarios se muestren siempre como texto.","files":{"index.html":"<main>\n  <h1>Comentarios</h1>\n  <form id=\"f\"><label for=\"txt\">Comentario</label><input id=\"txt\"><button>Publicar</button></form>\n  <ul id=\"lista\"></ul>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"const f = document.getElementById(\"f\");\nconst lista = document.getElementById(\"lista\");\n\nf.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const txt = document.getElementById(\"txt\");\n  lista.innerHTML += \"<li>\" + txt.value + \"</li>\";\n  txt.value = \"\";\n});"},"tests":[{"name":"El ataque no se ejecuta","type":"dom","code":"type('#txt', '<img src=x onerror=\"window.__pwned=true\">'); $('#f').requestSubmit(); await wait(150); return window.__pwned !== true || 'El ataque se ejecutó (window.__pwned = true).';"},{"name":"El comentario se ve como texto","type":"dom","code":"return !$('#lista img') && $('#lista li:last-child').textContent.includes('<img');"},{"name":"Se siguen publicando comentarios normales","type":"dom","code":"type('#txt', 'Hola'); $('#f').requestSubmit(); await wait(20); return $('#lista li:last-child').textContent === 'Hola' && $('#txt').value === '';"}],"hints":["Crea el <li> con createElement y asigna textContent."],"solution":{"app.js":"const f = document.getElementById(\"f\");\nconst lista = document.getElementById(\"lista\");\n\nf.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const txt = document.getElementById(\"txt\");\n  const li = document.createElement(\"li\");\n  li.textContent = txt.value;\n  lista.append(li);\n  txt.value = \"\";\n});"}}$webwiz5$::jsonb, false),
  ('seg-href-javascript-01', 'Web personal con enlaces javascript:', 'El perfil enlaza a la web que escribe el usuario. 1) Explota: guarda la web javascript:window.__pwned=true y pulsa el enlace. 2) Parchea: solo se aceptan URLs http(s); con otra cosa se muestra «Web no válida» y no se crea el enlace.', 'seguridad', 'challenge', 'semi_senior', ARRAY['xss']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-href-javascript-01","title":"Web personal con enlaces javascript:","difficulty":"semi_senior","concepts":["xss"],"instructions":"El perfil enlaza a la web que escribe el usuario. 1) Explota: guarda la web javascript:window.__pwned=true y pulsa el enlace. 2) Parchea: solo se aceptan URLs http(s); con otra cosa se muestra «Web no válida» y no se crea el enlace.","files":{"index.html":"<main>\n  <h1>Tu perfil</h1>\n  <form id=\"f\"><label for=\"web\">Tu web</label><input id=\"web\"><button>Guardar</button></form>\n  <p id=\"salida\"></p>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"document.getElementById(\"f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const url = document.getElementById(\"web\").value.trim();\n  const salida = document.getElementById(\"salida\");\n  salida.textContent = \"\";\n  const a = document.createElement(\"a\");\n  a.href = url;\n  a.textContent = \"Visitar mi web\";\n  salida.append(a);\n});"},"tests":[{"name":"javascript: no crea enlace","type":"dom","code":"type('#web', 'javascript:window.__pwned=true'); $('#f').requestSubmit(); await wait(20); const a = $('#salida a'); if (a) a.click(); await wait(20); return (!a && window.__pwned !== true || 'El ataque se ejecutó (window.__pwned = true).') === true || 'Se creó un enlace con javascript:';"},{"name":"Variantes con mayúsculas y espacios también se bloquean","type":"dom","code":"type('#web', '  JaVaScRiPt:alert(1)'); $('#f').requestSubmit(); await wait(20); return !$('#salida a') && /no válida/i.test(text('#salida'));"},{"name":"Una web https se enlaza","type":"dom","code":"type('#web', 'https://orpira.es'); $('#f').requestSubmit(); await wait(20); return $('#salida a')?.href === 'https://orpira.es/';"}],"hints":["new URL(url).protocol te dice el esquema real (y lanza error si no es una URL).","Acepta solo \"http:\" y \"https:\"."],"solution":{"app.js":"document.getElementById(\"f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const url = document.getElementById(\"web\").value.trim();\n  const salida = document.getElementById(\"salida\");\n  salida.textContent = \"\";\n  let segura = null;\n  try {\n    const u = new URL(url);\n    if (u.protocol === \"http:\" || u.protocol === \"https:\") segura = u.href;\n  } catch {}\n  if (!segura) {\n    salida.textContent = \"Web no válida\";\n    return;\n  }\n  const a = document.createElement(\"a\");\n  a.href = segura;\n  a.textContent = \"Visitar mi web\";\n  salida.append(a);\n});"}}$webwiz5$::jsonb, false),
  ('seg-atributo-01', 'Inyección en un atributo', 'Las tarjetas se construyen concatenando HTML con el nombre del usuario en un atributo alt. 1) Explota con el nombre: x" onerror="window.__pwned=true. 2) Parchea construyendo los elementos con la API del DOM.', 'seguridad', 'challenge', 'semi_senior', ARRAY['xss']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-atributo-01","title":"Inyección en un atributo","difficulty":"semi_senior","concepts":["xss"],"instructions":"Las tarjetas se construyen concatenando HTML con el nombre del usuario en un atributo alt. 1) Explota con el nombre: x\" onerror=\"window.__pwned=true. 2) Parchea construyendo los elementos con la API del DOM.","files":{"index.html":"<main>\n  <h1>Equipo</h1>\n  <form id=\"f\"><label for=\"nombre\">Nombre</label><input id=\"nombre\"><button>Añadir</button></form>\n  <div id=\"equipo\"></div>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"const AVATAR = \"data:image/gif;base64,R0lGODlhAQABAAAAACw=\";\ndocument.getElementById(\"f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const nombre = document.getElementById(\"nombre\").value;\n  document.getElementById(\"equipo\").insertAdjacentHTML(\n    \"beforeend\",\n    '<figure><img src=\"' + AVATAR + '\" alt=\"' + nombre + '\"><figcaption>' + nombre + \"</figcaption></figure>\"\n  );\n});"},"tests":[{"name":"El ataque no se ejecuta","type":"dom","code":"type('#nombre', 'x\" src=\"nada\" onerror=\"window.__pwned=true'); $('#f').requestSubmit(); await wait(200); return window.__pwned !== true || 'El ataque se ejecutó (window.__pwned = true).';"},{"name":"No se cuelan atributos","type":"dom","code":"return $$('#equipo img').every((i) => !i.hasAttribute('onerror'));"},{"name":"Una persona normal se añade con su nombre","type":"dom","code":"type('#nombre', 'Ane'); $('#f').requestSubmit(); await wait(20); const f = $$('#equipo figure').at(-1); return f.querySelector('img').alt === 'Ane' && f.querySelector('figcaption').textContent === 'Ane';"}],"hints":["createElement('img') y luego img.alt = nombre: el navegador lo escapa por ti."],"solution":{"app.js":"const AVATAR = \"data:image/gif;base64,R0lGODlhAQABAAAAACw=\";\ndocument.getElementById(\"f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const nombre = document.getElementById(\"nombre\").value;\n  const figure = document.createElement(\"figure\");\n  const img = document.createElement(\"img\");\n  img.src = AVATAR;\n  img.alt = nombre;\n  const cap = document.createElement(\"figcaption\");\n  cap.textContent = nombre;\n  figure.append(img, cap);\n  document.getElementById(\"equipo\").append(figure);\n});"}}$webwiz5$::jsonb, false),
  ('seg-eval-json-01', 'eval para leer la respuesta del servidor', 'La app lee la configuración del servidor con eval. El servidor (simulado) ha sido comprometido y devuelve código. Parchea app.js para leer JSON de forma segura; si la respuesta no es JSON válido, muestra «Configuración no válida».', 'seguridad', 'challenge', 'junior', ARRAY['seguridad-eval']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-eval-json-01","title":"eval para leer la respuesta del servidor","difficulty":"junior","concepts":["seguridad-eval"],"instructions":"La app lee la configuración del servidor con eval. El servidor (simulado) ha sido comprometido y devuelve código. Parchea app.js para leer JSON de forma segura; si la respuesta no es JSON válido, muestra «Configuración no válida».","run":{"network":[{"method":"GET","url":"/api/config","status":200,"body":"({ tema: (window.__pwned = true, 'oscuro') })"}]},"files":{"index.html":"<main><h1>Panel</h1><p id=\"estado\">Cargando…</p></main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"async function cargar() {\n  const res = await fetch(\"/api/config\");\n  const config = eval(\"(\" + (await res.text()) + \")\");\n  document.getElementById(\"estado\").textContent = \"Tema: \" + config.tema;\n}\ncargar();"},"tests":[{"name":"La respuesta maliciosa no se ejecuta","type":"dom","code":"await wait(150); return window.__pwned !== true || 'El ataque se ejecutó (window.__pwned = true).';"},{"name":"Avisa de configuración no válida","type":"dom","code":"return /no válida/i.test(text('#estado')) || ('Estado: ' + text('#estado'));"}],"hints":["res.json() o JSON.parse(texto) solo aceptan datos, nunca ejecutan código.","Envuélvelo en try/catch para mostrar el aviso."],"solution":{"app.js":"async function cargar() {\n  const estado = document.getElementById(\"estado\");\n  try {\n    const res = await fetch(\"/api/config\");\n    const config = await res.json();\n    estado.textContent = \"Tema: \" + config.tema;\n  } catch {\n    estado.textContent = \"Configuración no válida\";\n  }\n}\ncargar();"}}$webwiz5$::jsonb, false),
  ('seg-postmessage-01', 'postMessage sin comprobar el origen', 'El widget recibe el nombre del usuario por postMessage desde https://webwiz.app y lo pinta con innerHTML. Cualquier web que lo incruste puede enviarle mensajes. Parchea: ignora mensajes de otros orígenes y pinta el nombre como texto.', 'seguridad', 'challenge', 'senior', ARRAY['xss']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-postmessage-01","title":"postMessage sin comprobar el origen","difficulty":"senior","concepts":["xss"],"instructions":"El widget recibe el nombre del usuario por postMessage desde https://webwiz.app y lo pinta con innerHTML. Cualquier web que lo incruste puede enviarle mensajes. Parchea: ignora mensajes de otros orígenes y pinta el nombre como texto.","files":{"index.html":"<main><h1>Widget</h1><p>Hola, <span id=\"nombre\">invitado</span></p></main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"window.addEventListener(\"message\", (e) => {\n  if (e.data && e.data.tipo === \"usuario\") {\n    document.getElementById(\"nombre\").innerHTML = e.data.nombre;\n  }\n});"},"tests":[{"name":"Ignora mensajes de otros orígenes","type":"dom","code":"window.dispatchEvent(new MessageEvent('message', { data: { tipo: 'usuario', nombre: 'Mallory' }, origin: 'https://malo.example' })); await wait(10); return text('#nombre') === 'invitado' || 'Se aceptó un mensaje de https://malo.example';"},{"name":"El nombre se pinta como texto","type":"dom","code":"window.dispatchEvent(new MessageEvent('message', { data: { tipo: 'usuario', nombre: '<img src=x onerror=\"window.__pwned=true\">' }, origin: 'https://webwiz.app' })); await wait(150); return (window.__pwned !== true || 'El ataque se ejecutó (window.__pwned = true).') === true && !$('#nombre img');"},{"name":"Acepta mensajes del origen de confianza","type":"dom","code":"window.dispatchEvent(new MessageEvent('message', { data: { tipo: 'usuario', nombre: 'Ane' }, origin: 'https://webwiz.app' })); await wait(10); return text('#nombre') === 'Ane';"}],"hints":["Comprueba e.origin === \"https://webwiz.app\" antes de nada.","textContent en lugar de innerHTML."],"solution":{"app.js":"const ORIGEN = \"https://webwiz.app\";\nwindow.addEventListener(\"message\", (e) => {\n  if (e.origin !== ORIGEN) return;\n  if (e.data && e.data.tipo === \"usuario\") {\n    document.getElementById(\"nombre\").textContent = String(e.data.nombre);\n  }\n});"}}$webwiz5$::jsonb, false),
  ('seg-settimeout-string-01', 'setTimeout con texto: eval disfrazado', 'El recordatorio programa el aviso con setTimeout("mostrar(''" + texto + "'')"), que evalúa el texto como código. 1) Explota con el texto: '');window.__pwned=true;('' 2) Parchea pasando una función.', 'seguridad', 'challenge', 'semi_senior', ARRAY['seguridad-eval']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-settimeout-string-01","title":"setTimeout con texto: eval disfrazado","difficulty":"semi_senior","concepts":["seguridad-eval"],"instructions":"El recordatorio programa el aviso con setTimeout(\"mostrar('\" + texto + \"')\"), que evalúa el texto como código. 1) Explota con el texto: ');window.__pwned=true;(' 2) Parchea pasando una función.","files":{"index.html":"<main>\n  <h1>Recordatorio</h1>\n  <form id=\"f\"><label for=\"txt\">Texto</label><input id=\"txt\"><button>Programar</button></form>\n  <p id=\"aviso\" role=\"status\"></p>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"function mostrar(texto) {\n  document.getElementById(\"aviso\").textContent = \"⏰ \" + texto;\n}\ndocument.getElementById(\"f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const texto = document.getElementById(\"txt\").value;\n  setTimeout(\"mostrar('\" + texto + \"')\", 50);\n});"},"tests":[{"name":"El texto no se ejecuta como código","type":"dom","code":"type('#txt', \"');window.__pwned=true;('\"); $('#f').requestSubmit(); await wait(150); return window.__pwned !== true || 'El ataque se ejecutó (window.__pwned = true).';"},{"name":"Textos con comillas se muestran bien","type":"dom","code":"type('#txt', \"Llamar a O'Neill\"); $('#f').requestSubmit(); await wait(150); return text('#aviso') === \"⏰ Llamar a O'Neill\";"}],"hints":["setTimeout(() => mostrar(texto), 50)"],"solution":{"app.js":"function mostrar(texto) {\n  document.getElementById(\"aviso\").textContent = \"⏰ \" + texto;\n}\ndocument.getElementById(\"f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const texto = document.getElementById(\"txt\").value;\n  setTimeout(() => mostrar(texto), 50);\n});"}}$webwiz5$::jsonb, false),
  ('seg-open-redirect-01', 'Redirección abierta tras el login', 'Tras iniciar sesión, la app redirige al valor de ?next= sin comprobarlo: un enlace de phishing puede llevar a otra web. Implementa destinoSeguro(next): solo rutas internas que empiezan por una sola «/»; cualquier otra cosa → «/panel».', 'seguridad', 'challenge', 'semi_senior', ARRAY['seguridad-credenciales']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-open-redirect-01","title":"Redirección abierta tras el login","difficulty":"semi_senior","concepts":["seguridad-credenciales"],"instructions":"Tras iniciar sesión, la app redirige al valor de ?next= sin comprobarlo: un enlace de phishing puede llevar a otra web. Implementa destinoSeguro(next): solo rutas internas que empiezan por una sola «/»; cualquier otra cosa → «/panel».","files":{"index.html":"<main><h1>Acceso</h1><p>Abre la consola: las pruebas llaman a destinoSeguro().</p></main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"function destinoSeguro(next) {\n  return next || \"/panel\";\n}"},"tests":[{"name":"Rutas internas permitidas","type":"js","code":"return destinoSeguro('/facturas?mes=10') === '/facturas?mes=10' && destinoSeguro('/') === '/';"},{"name":"Webs externas bloqueadas","type":"js","code":"return ['https://malo.example', 'http://malo.example/panel', 'javascript:alert(1)'].every((u) => destinoSeguro(u) === '/panel');"},{"name":"Trucos con // y barras invertidas bloqueados","type":"js","code":"return ['//malo.example', '/\\\\malo.example', '\\\\\\\\malo.example', ' /x'].every((u) => destinoSeguro(u) === '/panel');"},{"name":"Sin next va al panel","type":"js","code":"return destinoSeguro(null) === '/panel' && destinoSeguro('') === '/panel';"}],"hints":["//dominio es una URL a otro sitio (protocolo relativo).","Exige que empiece por \"/\" y que el segundo carácter no sea \"/\" ni \"\\\\\"."],"solution":{"app.js":"function destinoSeguro(next) {\n  if (typeof next !== \"string\") return \"/panel\";\n  if (!next.startsWith(\"/\") || next.startsWith(\"//\") || next.startsWith(\"/\\\\\")) return \"/panel\";\n  return next;\n}"}}$webwiz5$::jsonb, false),
  ('seg-proto-pollution-01', 'Contaminación del prototipo al fusionar ajustes', 'fusionar(destino, origen) copia en profundidad los ajustes que llegan en JSON. Un JSON con "__proto__" contamina Object.prototype y todos los objetos heredan la propiedad. Parchea fusionar para ignorar __proto__, constructor y prototype.', 'seguridad', 'challenge', 'senior', ARRAY['seguridad-eval']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-proto-pollution-01","title":"Contaminación del prototipo al fusionar ajustes","difficulty":"senior","concepts":["seguridad-eval"],"instructions":"fusionar(destino, origen) copia en profundidad los ajustes que llegan en JSON. Un JSON con \"__proto__\" contamina Object.prototype y todos los objetos heredan la propiedad. Parchea fusionar para ignorar __proto__, constructor y prototype.","files":{"index.html":"<main><h1>Ajustes</h1></main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"function fusionar(destino, origen) {\n  for (const clave in origen) {\n    const valor = origen[clave];\n    if (valor && typeof valor === \"object\") {\n      if (!destino[clave] || typeof destino[clave] !== \"object\") destino[clave] = {};\n      fusionar(destino[clave], valor);\n    } else {\n      destino[clave] = valor;\n    }\n  }\n  return destino;\n}"},"tests":[{"name":"__proto__ no contamina los objetos","type":"js","code":"fusionar({}, JSON.parse('{\"__proto__\": {\"admin\": true}}')); return ({}).admin === undefined || 'Object.prototype quedó contaminado';"},{"name":"constructor.prototype tampoco","type":"js","code":"fusionar({}, JSON.parse('{\"constructor\": {\"prototype\": {\"rol\": \"root\"}}}')); return ({}).rol === undefined;"},{"name":"Fusiona ajustes anidados normales","type":"js","code":"const r = fusionar({ tema: { color: 'azul', tam: 14 } }, { tema: { color: 'rojo' }, idioma: 'es' }); return eq(r, { tema: { color: 'rojo', tam: 14 }, idioma: 'es' });"}],"hints":["Salta las claves \"__proto__\", \"constructor\" y \"prototype\".","Usa Object.keys(origen) en lugar de for…in para no recorrer heredadas."],"solution":{"app.js":"const PROHIBIDAS = new Set([\"__proto__\", \"constructor\", \"prototype\"]);\nfunction fusionar(destino, origen) {\n  for (const clave of Object.keys(origen)) {\n    if (PROHIBIDAS.has(clave)) continue;\n    const valor = origen[clave];\n    if (valor && typeof valor === \"object\") {\n      if (!Object.prototype.hasOwnProperty.call(destino, clave) || typeof destino[clave] !== \"object\") destino[clave] = {};\n      fusionar(destino[clave], valor);\n    } else {\n      destino[clave] = valor;\n    }\n  }\n  return destino;\n}"}}$webwiz5$::jsonb, false),
  ('seg-calculadora-eval-01', 'Calculadora que evalúa cualquier cosa', 'calcular(expr) usa new Function para operar. 1) Explota: calcular("(window.__pwned = true)") en la consola. 2) Parchea: acepta solo números, + - * /, paréntesis y espacios; si hay otra cosa, lanza un Error("Expresión no válida").', 'seguridad', 'challenge', 'senior', ARRAY['seguridad-eval']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-calculadora-eval-01","title":"Calculadora que evalúa cualquier cosa","difficulty":"senior","concepts":["seguridad-eval"],"instructions":"calcular(expr) usa new Function para operar. 1) Explota: calcular(\"(window.__pwned = true)\") en la consola. 2) Parchea: acepta solo números, + - * /, paréntesis y espacios; si hay otra cosa, lanza un Error(\"Expresión no válida\").","files":{"index.html":"<main><h1>Calculadora</h1></main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"function calcular(expr) {\n  return new Function(\"return (\" + expr + \")\")();\n}"},"tests":[{"name":"Opera bien","type":"js","code":"return calcular('2 + 3 * 4') === 14 && calcular('(10 - 4) / 3') === 2 && calcular('1.5*2') === 3;"},{"name":"Rechaza código","type":"js","code":"const malos = ['alert(1)', 'self.x=1', 'constructor', '2;fetch(1)', '`1`']; return malos.every((m) => { try { calcular(m); return false; } catch (e) { return /no válida/i.test(e.message); } });"},{"name":"No ejecuta asignaciones","type":"js","code":"try { calcular('(self.__pwned = true)'); } catch {} return self.__pwned !== true;"}],"hints":["Valida la expresión con una expresión regular antes de evaluarla: /^[\\d+\\-*/().\\s]+$/","Con la lista blanca, ya no hay letras ni = que permitan acceder a nada."],"solution":{"app.js":"function calcular(expr) {\n  if (typeof expr !== \"string\" || !/^[\\d+\\-*/().\\s]+$/.test(expr)) throw new Error(\"Expresión no válida\");\n  return new Function(\"return (\" + expr + \")\")();\n}"}}$webwiz5$::jsonb, false),
  ('seg-token-url-01', 'El token de sesión se filtra en la URL', 'Para compartir un informe, la app genera un enlace que incluye el token de sesión en la query (?token=…). Cualquiera con el enlace (o los logs del servidor) puede suplantar al usuario. Parchea enlaceCompartir(informeId) para que no incluya el token: el enlace solo lleva el id del informe.', 'seguridad', 'challenge', 'semi_senior', ARRAY['seguridad-credenciales']::TEXT[], $webwiz5${"category":"seguridad","editable":["app.js"],"id":"seg-token-url-01","title":"El token de sesión se filtra en la URL","difficulty":"semi_senior","concepts":["seguridad-credenciales"],"instructions":"Para compartir un informe, la app genera un enlace que incluye el token de sesión en la query (?token=…). Cualquiera con el enlace (o los logs del servidor) puede suplantar al usuario. Parchea enlaceCompartir(informeId) para que no incluya el token: el enlace solo lleva el id del informe.","files":{"index.html":"<main><h1>Informes</h1></main>","styles.css":"body { font-family: system-ui, sans-serif; padding: 16px; }\n.alerta { color: #a84b00; }","app.js":"const sesion = { token: \"eyJhbGciOi.secreto.firma\" };\n\nfunction enlaceCompartir(informeId) {\n  return \"https://app.webwiz.dev/informes/\" + informeId + \"?token=\" + sesion.token;\n}"},"tests":[{"name":"El enlace no contiene el token","type":"js","code":"return !enlaceCompartir(7).includes(sesion.token) || 'El enlace incluye el token de sesión';"},{"name":"El enlace apunta al informe","type":"js","code":"return enlaceCompartir(7) === 'https://app.webwiz.dev/informes/7';"},{"name":"El id se codifica","type":"js","code":"return enlaceCompartir('a b') === 'https://app.webwiz.dev/informes/a%20b';"}],"hints":["El servidor debe comprobar el acceso con la sesión de quien abre el enlace, no con un token pegado en la URL.","encodeURIComponent(informeId)."],"solution":{"app.js":"const sesion = { token: \"eyJhbGciOi.secreto.firma\" };\n\nfunction enlaceCompartir(informeId) {\n  return \"https://app.webwiz.dev/informes/\" + encodeURIComponent(informeId);\n}"}}$webwiz5$::jsonb, false),
  ('perf-cls-imagen-01', 'El texto salta cuando carga la foto', 'La foto de portada no tiene dimensiones: cuando llega (simulado a los 300 ms) empuja el artículo hacia abajo y dispara el CLS. Reserva su espacio (width/height o aspect-ratio) para que el artículo no se mueva. La foto debe medir 600×300 en escritorio y adaptarse en móvil.', 'rendimiento', 'challenge', 'junior', ARRAY['web-vitals']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-cls-imagen-01","title":"El texto salta cuando carga la foto","difficulty":"junior","concepts":["web-vitals"],"editable":["index.html","styles.css"],"instructions":"La foto de portada no tiene dimensiones: cuando llega (simulado a los 300 ms) empuja el artículo hacia abajo y dispara el CLS. Reserva su espacio (width/height o aspect-ratio) para que el artículo no se mueva. La foto debe medir 600×300 en escritorio y adaptarse en móvil.","files":{"index.html":"<main>\n  <img id=\"portada\" alt=\"Puerto de Bermeo\" style=\"max-width: 100%\">\n  <article id=\"articulo\"><h1>Una mañana en Bermeo</h1><p>El puerto despierta antes que el sol…</p></article>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\nimg { display: block; }","app.js":"setTimeout(() => {\n  const img = document.getElementById(\"portada\");\n  img.style.width = \"600px\";\n  img.style.height = \"300px\";\n  img.src = \"data:image/gif;base64,R0lGODlhAQABAAAAACw=\";\n}, 300);"},"tests":[{"name":"El artículo no se desplaza al cargar la foto","type":"dom","code":"const antes = rect('#articulo').top; await wait(400); const despues = rect('#articulo').top; return near(antes, despues, 1) || ('El artículo se desplazó ' + Math.round(despues - antes) + ' px');"},{"name":"La foto mide 600×300","type":"dom","code":"await wait(350); const r = rect('#portada'); return near(r.width, 600, 1) && near(r.height, 300, 1);"}],"hints":["Añade width=\"600\" height=\"300\" a la etiqueta: el navegador reserva el hueco antes de que llegue la imagen.","Con height: auto en CSS se mantiene la proporción en móvil."],"solution":{"index.html":"<main>\n  <img id=\"portada\" alt=\"Puerto de Bermeo\" width=\"600\" height=\"300\" style=\"max-width: 100%\">\n  <article id=\"articulo\"><h1>Una mañana en Bermeo</h1><p>El puerto despierta antes que el sol…</p></article>\n</main>"}}$webwiz5$::jsonb, false),
  ('perf-cls-banner-01', 'El banner de cookies empuja la página', 'El aviso de cookies se inserta al principio del body a los 250 ms y desplaza todo el contenido. Sin tocar el JavaScript, haz que aparezca superpuesto (fijo abajo) para que no mueva nada.', 'rendimiento', 'challenge', 'junior', ARRAY['web-vitals']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-cls-banner-01","title":"El banner de cookies empuja la página","difficulty":"junior","concepts":["web-vitals"],"editable":["styles.css"],"instructions":"El aviso de cookies se inserta al principio del body a los 250 ms y desplaza todo el contenido. Sin tocar el JavaScript, haz que aparezca superpuesto (fijo abajo) para que no mueva nada.","files":{"index.html":"<main id=\"contenido\"><h1>Noticias</h1><p>Última hora desde Bilbao…</p></main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\n.cookies { padding: 16px; background: #161b22; color: white; }","app.js":"setTimeout(() => {\n  const aviso = document.createElement(\"div\");\n  aviso.className = \"cookies\";\n  aviso.textContent = \"Usamos cookies técnicas.\";\n  document.body.prepend(aviso);\n}, 250);"},"tests":[{"name":"El contenido no se mueve","type":"dom","code":"const a = rect('#contenido').top; await wait(350); const b = rect('#contenido').top; return near(a, b, 1) || ('El contenido bajó ' + Math.round(b - a) + ' px');"},{"name":"El aviso se ve abajo","type":"dom","code":"await wait(300); const r = rect('.cookies'); return r.height > 0 && near(r.bottom, window.innerHeight, 2);"}],"hints":[".cookies { position: fixed; left: 0; right: 0; bottom: 0; }"],"solution":{"styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\n.cookies { position: fixed; left: 0; right: 0; bottom: 0; padding: 16px; background: #161b22; color: white; }"}}$webwiz5$::jsonb, false),
  ('perf-dom-lote-01', '1000 filas insertadas una a una', 'pintar() añade 1000 filas haciendo innerHTML += en cada vuelta: el navegador reconstruye la lista 1000 veces. Reescríbelo para insertar todas las filas de una vez (DocumentFragment o replaceChildren). Se mide cuántas mutaciones recibe la lista.', 'rendimiento', 'challenge', 'semi_senior', ARRAY['render-bloqueo']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-dom-lote-01","title":"1000 filas insertadas una a una","difficulty":"semi_senior","concepts":["render-bloqueo"],"editable":["app.js"],"instructions":"pintar() añade 1000 filas haciendo innerHTML += en cada vuelta: el navegador reconstruye la lista 1000 veces. Reescríbelo para insertar todas las filas de una vez (DocumentFragment o replaceChildren). Se mide cuántas mutaciones recibe la lista.","files":{"index.html":"<main><h1>Inventario</h1><ul id=\"lista\"></ul></main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }","app.js":"const items = Array.from({ length: 1000 }, (_, i) => \"Producto \" + (i + 1));\nconst lista = document.getElementById(\"lista\");\n\nfunction pintar() {\n  lista.innerHTML = \"\";\n  for (const item of items) {\n    lista.innerHTML += \"<li>\" + item + \"</li>\";\n  }\n}\n\nwindow.pintar = pintar;\npintar();"},"tests":[{"name":"Pinta las 1000 filas","type":"dom","code":"return $$('#lista li').length === 1000 && text('#lista li:last-child') === 'Producto 1000';"},{"name":"Como mucho 2 mutaciones por repintado","type":"dom","code":"let n = 0; const mo = new MutationObserver((rs) => (n += rs.length)); mo.observe($('#lista'), { childList: true }); window.pintar(); await wait(0); mo.disconnect(); return n <= 2 || ('La lista recibió ' + n + ' mutaciones');"}],"hints":["Construye los <li> en un DocumentFragment y añádelo una sola vez.","lista.replaceChildren(...nodos) vacía y rellena en una única operación."],"solution":{"app.js":"const items = Array.from({ length: 1000 }, (_, i) => \"Producto \" + (i + 1));\nconst lista = document.getElementById(\"lista\");\n\nfunction pintar() {\n  const nodos = items.map((item) => {\n    const li = document.createElement(\"li\");\n    li.textContent = item;\n    return li;\n  });\n  lista.replaceChildren(...nodos);\n}\n\nwindow.pintar = pintar;\npintar();"}}$webwiz5$::jsonb, false),
  ('perf-debounce-01', 'Una petición por cada tecla', 'El buscador llama a la API en cada pulsación: escribir «bilbao» son 6 peticiones. Añade un debounce de 300 ms para que solo se busque cuando el usuario deja de escribir.', 'rendimiento', 'challenge', 'semi_senior', ARRAY['carga-recursos', 'closures']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-debounce-01","title":"Una petición por cada tecla","difficulty":"semi_senior","concepts":["carga-recursos","closures"],"editable":["app.js"],"instructions":"El buscador llama a la API en cada pulsación: escribir «bilbao» son 6 peticiones. Añade un debounce de 300 ms para que solo se busque cuando el usuario deja de escribir.","run":{"network":[{"method":"GET","url":"/api/buscar","status":200,"body":{"resultados":["Bilbao","Bilbao La Vieja"]},"delayMs":20}]},"files":{"index.html":"<main><h1>Buscar</h1><label for=\"q\">Ciudad</label><input id=\"q\"><ul id=\"res\"></ul></main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }","app.js":"const q = document.getElementById(\"q\");\nconst res = document.getElementById(\"res\");\n\nasync function buscar(texto) {\n  const r = await fetch(\"/api/buscar?q=\" + encodeURIComponent(texto));\n  const { resultados } = await r.json();\n  res.replaceChildren(...resultados.map((t) => Object.assign(document.createElement(\"li\"), { textContent: t })));\n}\n\nq.addEventListener(\"input\", () => buscar(q.value));"},"tests":[{"name":"Escribir una palabra hace una sola petición","type":"dom","code":"for (const t of ['b', 'bi', 'bil', 'bilb', 'bilba', 'bilbao']) { type('#q', t); await wait(30); } await wait(450); const n = requests().length; return n === 1 || ('Se hicieron ' + n + ' peticiones');"},{"name":"Busca el texto completo","type":"dom","code":"return requests().at(-1)?.url === '/api/buscar?q=bilbao' && $$('#res li').length === 2;"}],"hints":["Guarda el temporizador fuera del listener: clearTimeout(t); t = setTimeout(…, 300)."],"solution":{"app.js":"const q = document.getElementById(\"q\");\nconst res = document.getElementById(\"res\");\n\nasync function buscar(texto) {\n  const r = await fetch(\"/api/buscar?q=\" + encodeURIComponent(texto));\n  const { resultados } = await r.json();\n  res.replaceChildren(...resultados.map((t) => Object.assign(document.createElement(\"li\"), { textContent: t })));\n}\n\nlet t;\nq.addEventListener(\"input\", () => {\n  clearTimeout(t);\n  t = setTimeout(() => buscar(q.value), 300);\n});"}}$webwiz5$::jsonb, false),
  ('perf-memo-01', 'El cálculo caro se repite en cada clic', 'Cada clic en «Mostrar total» recalcula las estadísticas de 200 000 ventas aunque los datos no cambien. Guarda el resultado (memoización) y recalcula solo cuando se añade una venta. window.__calculos cuenta las veces que se calcula.', 'rendimiento', 'challenge', 'semi_senior', ARRAY['closures']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-memo-01","title":"El cálculo caro se repite en cada clic","difficulty":"semi_senior","concepts":["closures"],"editable":["app.js"],"instructions":"Cada clic en «Mostrar total» recalcula las estadísticas de 200 000 ventas aunque los datos no cambien. Guarda el resultado (memoización) y recalcula solo cuando se añade una venta. window.__calculos cuenta las veces que se calcula.","files":{"index.html":"<main><h1>Ventas</h1><button id=\"mostrar\">Mostrar total</button><button id=\"nueva\">Añadir venta</button><p id=\"total\"></p></main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }","app.js":"const ventas = Array.from({ length: 200000 }, (_, i) => (i % 100) + 1);\nwindow.__calculos = 0;\n\nfunction estadisticas() {\n  window.__calculos++;\n  const total = ventas.reduce((a, b) => a + b, 0);\n  return { total, media: total / ventas.length };\n}\n\ndocument.getElementById(\"mostrar\").addEventListener(\"click\", () => {\n  document.getElementById(\"total\").textContent = \"Total: \" + estadisticas().total;\n});\ndocument.getElementById(\"nueva\").addEventListener(\"click\", () => {\n  ventas.push(50);\n});"},"tests":[{"name":"Cinco clics, un solo cálculo","type":"dom","code":"for (let i = 0; i < 5; i++) click('#mostrar'); return window.__calculos === 1 || ('Se calculó ' + window.__calculos + ' veces');"},{"name":"Una venta nueva actualiza el total","type":"dom","code":"click('#mostrar'); const antes = text('#total'); click('#nueva'); click('#mostrar'); return text('#total') !== antes && text('#total') === 'Total: ' + (10100000 + 50);"}],"hints":["Guarda el resultado en una variable (cache = null) y devuélvelo si existe.","Al añadir una venta, invalida la caché (cache = null)."],"solution":{"app.js":"const ventas = Array.from({ length: 200000 }, (_, i) => (i % 100) + 1);\nwindow.__calculos = 0;\nlet cache = null;\n\nfunction estadisticas() {\n  if (cache) return cache;\n  window.__calculos++;\n  const total = ventas.reduce((a, b) => a + b, 0);\n  cache = { total, media: total / ventas.length };\n  return cache;\n}\n\ndocument.getElementById(\"mostrar\").addEventListener(\"click\", () => {\n  document.getElementById(\"total\").textContent = \"Total: \" + estadisticas().total;\n});\ndocument.getElementById(\"nueva\").addEventListener(\"click\", () => {\n  ventas.push(50);\n  cache = null;\n});"}}$webwiz5$::jsonb, false),
  ('perf-lazy-01', 'Todas las imágenes se descargan a la vez', 'La galería tiene 8 fotos y todas compiten con la portada (el elemento LCP). Marca la portada con fetchpriority="high" y difiere las demás con loading="lazy". Todas deben tener width y height.', 'rendimiento', 'challenge', 'junior', ARRAY['carga-recursos', 'web-vitals']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-lazy-01","title":"Todas las imágenes se descargan a la vez","difficulty":"junior","concepts":["carga-recursos","web-vitals"],"editable":["index.html"],"instructions":"La galería tiene 8 fotos y todas compiten con la portada (el elemento LCP). Marca la portada con fetchpriority=\"high\" y difiere las demás con loading=\"lazy\". Todas deben tener width y height.","files":{"index.html":"<main>\n  <img id=\"portada\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Portada\" width=\"800\" height=\"400\">\n  <div class=\"galeria\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 1\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 2\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 3\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 4\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 5\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 6\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 7\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 8\">\n  </div>\n</main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\nimg { max-width: 100%; height: auto; }\n.foto { width: 200px; }","app.js":""},"tests":[{"name":"La portada tiene prioridad alta y no es lazy","type":"dom","code":"const p = $('#portada'); return p.getAttribute('fetchpriority') === 'high' && p.getAttribute('loading') !== 'lazy';"},{"name":"Las 8 fotos de la galería son lazy","type":"dom","code":"return $$('.foto').length === 8 && $$('.foto').every((i) => i.getAttribute('loading') === 'lazy');"},{"name":"Todas tienen dimensiones","type":"dom","code":"return $$('img').every((i) => i.getAttribute('width') && i.getAttribute('height'));"}],"hints":["<img loading=\"lazy\" width=\"200\" height=\"150\" …>","No pongas lazy en la imagen más grande que se ve al cargar."],"solution":{"index.html":"<main>\n  <img id=\"portada\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Portada\" width=\"800\" height=\"400\" fetchpriority=\"high\">\n  <div class=\"galeria\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 1\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 2\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 3\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 4\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 5\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 6\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 7\" width=\"200\" height=\"150\" loading=\"lazy\">\n    <img class=\"foto\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACw=\" alt=\"Foto 8\" width=\"200\" height=\"150\" loading=\"lazy\">\n  </div>\n</main>"}}$webwiz5$::jsonb, false),
  ('perf-script-bloqueante-01', 'Scripts que bloquean el primer pintado', 'Dos scripts externos están en el <head> sin defer ni async: el navegador deja de pintar hasta descargarlos. Haz que el de analítica sea async (no depende de nada) y el del widget defer (necesita el DOM), sin moverlos del head.', 'rendimiento', 'challenge', 'junior', ARRAY['render-bloqueo']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-script-bloqueante-01","title":"Scripts que bloquean el primer pintado","difficulty":"junior","concepts":["render-bloqueo"],"editable":["index.html"],"instructions":"Dos scripts externos están en el <head> sin defer ni async: el navegador deja de pintar hasta descargarlos. Haz que el de analítica sea async (no depende de nada) y el del widget defer (necesita el DOM), sin moverlos del head.","files":{"index.html":"<head>\n  <script src=\"/vendor/analitica.js\"></script>\n  <script src=\"/vendor/widget-chat.js\"></script>\n</head>\n<body>\n  <main><h1>Tienda</h1><p>Bienvenida.</p></main>\n</body>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }","app.js":""},"tests":[{"name":"La analítica es async","type":"dom","code":"const s = $('script[src$=\"analitica.js\"]'); return !!s && s.async && s.parentElement === document.head;"},{"name":"El widget es defer","type":"dom","code":"const s = $('script[src$=\"widget-chat.js\"]'); return !!s && s.defer && !s.async && s.parentElement === document.head;"}],"hints":["async: se ejecuta en cuanto llega, en cualquier orden.","defer: espera a que el HTML esté analizado y respeta el orden."],"solution":{"index.html":"<head>\n  <script src=\"/vendor/analitica.js\" async></script>\n  <script src=\"/vendor/widget-chat.js\" defer></script>\n</head>\n<body>\n  <main><h1>Tienda</h1><p>Bienvenida.</p></main>\n</body>"}}$webwiz5$::jsonb, false),
  ('perf-animacion-transform-01', 'Animación que recalcula el layout', 'El menú lateral se anima cambiando left, lo que obliga a recalcular el layout en cada fotograma. Anímalo con transform (translateX), que se resuelve en la GPU, manteniendo la misma posición abierta y cerrada.', 'rendimiento', 'challenge', 'semi_senior', ARRAY['render-bloqueo']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-animacion-transform-01","title":"Animación que recalcula el layout","difficulty":"semi_senior","concepts":["render-bloqueo"],"editable":["styles.css"],"instructions":"El menú lateral se anima cambiando left, lo que obliga a recalcular el layout en cada fotograma. Anímalo con transform (translateX), que se resuelve en la GPU, manteniendo la misma posición abierta y cerrada.","files":{"index.html":"<nav id=\"menu\" class=\"menu\">Menú</nav><button id=\"toggle\">Abrir</button>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.menu { position: fixed; top: 0; bottom: 0; left: -260px; width: 260px; background: #161b22; color: white; transition: left 0.01s; }\n.menu.abierto { left: 0; }","app.js":"document.getElementById(\"toggle\").addEventListener(\"click\", () => {\n  document.getElementById(\"menu\").classList.toggle(\"abierto\");\n});"},"tests":[{"name":"Solo se anima transform","type":"dom","code":"const t = style('#menu', 'transition-property'); return (/transform/.test(t) && !/left|all/.test(t)) || ('Se anima: ' + t);"},{"name":"Cerrado queda fuera de la pantalla","type":"dom","code":"await wait(50); return near(rect('#menu').right, 0, 1);"},{"name":"Abierto ocupa sus 260 px","type":"dom","code":"click('#toggle'); await wait(80); const r = rect('#menu'); click('#toggle'); return near(r.left, 0, 1) && near(r.width, 260, 1);"}],"hints":[".menu { left: 0; transform: translateX(-100%); transition: transform 0.2s; } .menu.abierto { transform: none; }"],"solution":{"styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n.menu { position: fixed; top: 0; bottom: 0; left: 0; width: 260px; background: #161b22; color: white; transform: translateX(-100%); transition: transform 0.01s; }\n.menu.abierto { transform: none; }"}}$webwiz5$::jsonb, false),
  ('perf-imagen-responsive-01', 'Una imagen de 2400 px para un hueco de 300', 'La ficha descarga siempre foto-2400.jpg aunque se muestra a 300 px. Ofrece las variantes 300w, 600w y 1200w con srcset y declara sizes="300px" para que el navegador elija la más pequeña suficiente.', 'rendimiento', 'challenge', 'semi_senior', ARRAY['carga-recursos']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-imagen-responsive-01","title":"Una imagen de 2400 px para un hueco de 300","difficulty":"semi_senior","concepts":["carga-recursos"],"editable":["index.html"],"instructions":"La ficha descarga siempre foto-2400.jpg aunque se muestra a 300 px. Ofrece las variantes 300w, 600w y 1200w con srcset y declara sizes=\"300px\" para que el navegador elija la más pequeña suficiente.","files":{"index.html":"<main>\n  <h1>Zapatillas Trail X</h1>\n  <img id=\"foto\" src=\"/img/foto-2400.jpg\" alt=\"Zapatillas Trail X\" width=\"300\" height=\"300\">\n</main>","styles.css":"body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }","app.js":""},"tests":[{"name":"srcset con las tres variantes","type":"dom","code":"const s = $('#foto').getAttribute('srcset') || ''; return ['foto-300.jpg 300w', 'foto-600.jpg 600w', 'foto-1200.jpg 1200w'].every((v) => s.includes(v)) || 'Falta alguna variante en srcset';"},{"name":"sizes indica el ancho mostrado","type":"dom","code":"return ($('#foto').getAttribute('sizes') || '').trim() === '300px';"},{"name":"Conserva alt y dimensiones","type":"dom","code":"const i = $('#foto'); return i.alt === 'Zapatillas Trail X' && i.getAttribute('width') === '300';"}],"hints":["srcset=\"/img/foto-300.jpg 300w, /img/foto-600.jpg 600w, /img/foto-1200.jpg 1200w\""],"solution":{"index.html":"<main>\n  <h1>Zapatillas Trail X</h1>\n  <img id=\"foto\" src=\"/img/foto-600.jpg\" srcset=\"/img/foto-300.jpg 300w, /img/foto-600.jpg 600w, /img/foto-1200.jpg 1200w\" sizes=\"300px\" alt=\"Zapatillas Trail X\" width=\"300\" height=\"300\">\n</main>"}}$webwiz5$::jsonb, false),
  ('perf-scroll-listener-01', 'El scroll ejecuta trabajo pesado en cada evento', 'actualizarBarra() lee y escribe el layout en cada evento scroll (pueden ser decenas por fotograma). Agrupa el trabajo con requestAnimationFrame para que se ejecute como mucho una vez por fotograma y registra el listener como pasivo. window.__actualizaciones cuenta las ejecuciones.', 'rendimiento', 'challenge', 'senior', ARRAY['render-bloqueo']::TEXT[], $webwiz5${"category":"rendimiento","id":"perf-scroll-listener-01","title":"El scroll ejecuta trabajo pesado en cada evento","difficulty":"senior","concepts":["render-bloqueo"],"editable":["app.js"],"instructions":"actualizarBarra() lee y escribe el layout en cada evento scroll (pueden ser decenas por fotograma). Agrupa el trabajo con requestAnimationFrame para que se ejecute como mucho una vez por fotograma y registra el listener como pasivo. window.__actualizaciones cuenta las ejecuciones.","files":{"index.html":"<div id=\"barra\"></div><main style=\"height: 3000px\"><h1>Artículo largo</h1></main>","styles.css":"body { margin: 0; font-family: system-ui, sans-serif; }\n#barra { position: fixed; top: 0; left: 0; height: 4px; background: #2f5bd3; width: 0; }","app.js":"window.__actualizaciones = 0;\nfunction actualizarBarra() {\n  window.__actualizaciones++;\n  const max = document.documentElement.scrollHeight - innerHeight;\n  document.getElementById(\"barra\").style.width = (scrollY / max) * 100 + \"%\";\n}\nwindow.addEventListener(\"scroll\", actualizarBarra);"},"tests":[{"name":"20 eventos seguidos, una actualización","type":"dom","code":"window.__actualizaciones = 0; for (let i = 0; i < 20; i++) window.dispatchEvent(new Event('scroll')); await wait(100); return window.__actualizaciones === 1 || ('Se actualizó ' + window.__actualizaciones + ' veces');"},{"name":"La barra sigue el scroll","type":"dom","code":"window.scrollTo(0, (document.documentElement.scrollHeight - innerHeight) / 2); window.dispatchEvent(new Event('scroll')); await wait(100); const w = parseFloat($('#barra').style.width); window.scrollTo(0, 0); return near(w, 50, 2) || ('Ancho: ' + w + '%');"}],"hints":["let pendiente = false; en el listener: if (!pendiente) { pendiente = true; requestAnimationFrame(() => { pendiente = false; actualizarBarra(); }); }","addEventListener('scroll', fn, { passive: true })"],"solution":{"app.js":"window.__actualizaciones = 0;\nfunction actualizarBarra() {\n  window.__actualizaciones++;\n  const max = document.documentElement.scrollHeight - innerHeight;\n  document.getElementById(\"barra\").style.width = (scrollY / max) * 100 + \"%\";\n}\nlet pendiente = false;\nwindow.addEventListener(\n  \"scroll\",\n  () => {\n    if (pendiente) return;\n    pendiente = true;\n    requestAnimationFrame(() => {\n      pendiente = false;\n      actualizarBarra();\n    });\n  },\n  { passive: true }\n);"}}$webwiz5$::jsonb, false),
  ('rev-01', 'Widget de comentarios con filtro por autor', 'Añade la lista de comentarios del artículo y un selector para filtrar por autor. Probado en local, todo funciona 👍', 'revisiones', 'review', 'semi_senior', ARRAY['xss', 'promises', 'event-loop']::TEXT[], $webwiz5${"id":"rev-01","type":"review","title":"Widget de comentarios con filtro por autor","description":"Añade la lista de comentarios del artículo y un selector para filtrar por autor. Probado en local, todo funciona 👍","file":"src/comentarios.js","language":"javascript","difficulty":"semi_senior","diff":" import { api } from \"./api.js\";\n \n+const lista = document.querySelector(\"#comentarios\");\n+const filtro = document.querySelector(\"#autor\");\n+\n+function pintar(comentarios) {\n+  lista.innerHTML = comentarios\n+    .map((c) => `<li><strong>${c.autor}</strong> ${c.texto}</li>`)\n+    .join(\"\");\n+}\n+\n+async function cargar(autor) {\n+  lista.setAttribute(\"aria-busy\", \"true\");\n+  const url = autor ? `/api/comentarios?autor=${encodeURIComponent(autor)}` : \"/api/comentarios\";\n+  const res = await api(url);\n+  const datos = await res.json();\n+  pintar(datos);\n+  lista.setAttribute(\"aria-busy\", \"false\");\n+}\n+\n+filtro.addEventListener(\"change\", () => {\n+  cargar(filtro.value);\n+});\n+\n+cargar();\n+\n+export function contar(comentarios) {\n+  return comentarios.reduce((n, c) => n + (c.texto.trim() ? 1 : 0), 0);\n+}\n+\n+export function resumen(comentarios) {\n+  const autores = new Set(comentarios.map((c) => c.autor));\n+  return `${contar(comentarios)} comentarios de ${autores.size} autores`;\n+}","issues":[{"id":"xss","category":"seguridad","match":"lista.innerHTML = comentarios","span":3,"title":"XSS: texto de usuario dentro de innerHTML","explanation":"autor y texto los escriben los usuarios. Con innerHTML, un comentario como <img src=x onerror=…> ejecuta código en el navegador de cada lector. Hay que crear los nodos y asignar textContent (o escapar el HTML).","concepts":["xss"]},{"id":"race","category":"bug","match":"const res = await api(url);","title":"Condición de carrera al cambiar el filtro","explanation":"Si el usuario cambia de autor dos veces seguidas, la respuesta antigua puede llegar después y pintar el filtro equivocado. Hay que cancelar la petición anterior (AbortController) o descartar respuestas que no sean la última.","concepts":["promises","event-loop"]},{"id":"ok","category":"bug","match":"const datos = await res.json();","title":"No se comprueba res.ok","explanation":"Un 500 o un 404 también resuelve fetch: res.json() fallará o pintará un objeto de error y aria-busy se quedará en true. Comprueba res.ok y usa try/finally para restaurar el estado.","concepts":["promises"]}]}$webwiz5$::jsonb, false),
  ('rev-02', 'Tabla de notas privadas con RLS', 'Crea la tabla notes para que cada usuario guarde sus notas. He activado RLS para que sea segura.', 'revisiones', 'review', 'senior', ARRAY['rls', 'sql-indices']::TEXT[], $webwiz5${"id":"rev-02","type":"review","title":"Tabla de notas privadas con RLS","description":"Crea la tabla notes para que cada usuario guarde sus notas. He activado RLS para que sea segura.","file":"supabase/migrations/20261101_notas.sql","language":"sql","difficulty":"senior","diff":"+CREATE TABLE notes (\n+  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n+  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n+  title TEXT NOT NULL CHECK (char_length(title) <= 120),\n+  body TEXT NOT NULL DEFAULT '',\n+  shared BOOLEAN NOT NULL DEFAULT false,\n+  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n+  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n+);\n+\n+ALTER TABLE notes ENABLE ROW LEVEL SECURITY;\n+\n+-- Cada usuario ve sus notas y las compartidas\n+CREATE POLICY \"Ver notas\" ON notes\n+  FOR SELECT TO authenticated\n+  USING (auth.uid() = user_id OR shared);\n+\n+-- Crear notas propias\n+CREATE POLICY \"Crear notas\" ON notes\n+  FOR INSERT TO authenticated\n+  WITH CHECK (true);\n+\n+-- Editar notas\n+CREATE POLICY \"Editar notas\" ON notes\n+  FOR UPDATE TO authenticated\n+  USING (true);\n+\n+-- Borrar notas propias\n+CREATE POLICY \"Borrar notas\" ON notes\n+  FOR DELETE TO authenticated\n+  USING (auth.uid() = user_id);\n+\n+-- Listado del usuario ordenado por fecha\n+CREATE VIEW my_notes AS\n+  SELECT id, title, updated_at FROM notes\n+  WHERE user_id = auth.uid()\n+  ORDER BY updated_at DESC;","issues":[{"id":"insert","category":"seguridad","match":"  WITH CHECK (true);","title":"INSERT sin comprobar el dueño","explanation":"WITH CHECK (true) permite insertar filas con el user_id de otra persona (notas \"en su nombre\"). Debe ser WITH CHECK (auth.uid() = user_id).","concepts":["rls"]},{"id":"update","category":"seguridad","match":"FOR UPDATE TO authenticated","span":2,"title":"Cualquiera puede editar cualquier nota","explanation":"USING (true) en UPDATE deja modificar notas ajenas, y sin WITH CHECK se puede incluso cambiar el user_id. Usa USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id).","concepts":["rls"]},{"id":"index","category":"rendimiento","match":"  WHERE user_id = auth.uid()","span":2,"title":"Falta índice por usuario y fecha","explanation":"La vista y las políticas filtran por user_id y ordenan por updated_at: sin un índice (user_id, updated_at DESC) cada consulta recorre la tabla entera cuando crece.","concepts":["sql-indices"]}]}$webwiz5$::jsonb, false),
  ('rev-03', 'Tarjeta de perfil con avatar y estado en línea', 'Componente ProfileCard: carga el usuario, muestra su avatar y refresca el estado "en línea" cada 30 s.', 'revisiones', 'review', 'semi_senior', ARRAY['react-hooks', 'a11y-imagenes']::TEXT[], $webwiz5${"id":"rev-03","type":"review","title":"Tarjeta de perfil con avatar y estado en línea","description":"Componente ProfileCard: carga el usuario, muestra su avatar y refresca el estado \"en línea\" cada 30 s.","file":"src/components/ProfileCard.tsx","language":"tsx","difficulty":"semi_senior","diff":" import { useEffect, useState } from \"react\";\n import { getUser, getPresence, type User } from \"../api\";\n \n+type Props = { userId: string };\n+\n+export default function ProfileCard({ userId }: Props) {\n+  const [user, setUser] = useState<User | null>(null);\n+  const [online, setOnline] = useState(false);\n+\n+  useEffect(() => {\n+    getUser(userId).then(setUser);\n+  });\n+\n+  useEffect(() => {\n+    const id = setInterval(async () => {\n+      setOnline(await getPresence(userId));\n+    }, 30_000);\n+  }, [userId]);\n+\n+  if (!user) return <p>Cargando…</p>;\n+\n+  return (\n+    <article className=\"card\">\n+      <img src={user.avatarUrl} width={64} height={64} />\n+      <h2>{user.name}</h2>\n+      <p className={online ? \"online\" : \"offline\"}>\n+        {online ? \"En línea\" : \"Desconectado\"}\n+      </p>\n+      <a href={`/perfil/${user.id}`}>Ver perfil</a>\n+    </article>\n+  );\n+}","issues":[{"id":"deps","category":"rendimiento","match":"    getUser(userId).then(setUser);","span":2,"title":"useEffect sin array de dependencias","explanation":"Sin dependencias el efecto se ejecuta tras cada render; setUser provoca otro render y otra petición: bucle infinito de peticiones. Debe ser [userId].","concepts":["react-hooks"]},{"id":"cleanup","category":"bug","match":"    const id = setInterval(async () => {","span":4,"title":"El intervalo nunca se limpia","explanation":"El efecto no devuelve () => clearInterval(id). Al cambiar de usuario o desmontar, el intervalo sigue vivo: fugas de memoria y estados de otro usuario.","concepts":["react-hooks"]},{"id":"alt","category":"accesibilidad","match":"<img src={user.avatarUrl}","title":"Imagen sin texto alternativo","explanation":"Sin alt el lector de pantalla lee la URL. Si el nombre ya aparece al lado, usa alt=\"\" (decorativa); si no, alt={`Avatar de ${user.name}`}.","concepts":["a11y-imagenes"]}]}$webwiz5$::jsonb, false),
  ('rev-04', 'Formulario de acceso con "recordarme"', 'Nuevo login: email, contraseña, recordar sesión y botón de entrar. Guardamos el token para no pedir login otra vez.', 'revisiones', 'review', 'junior', ARRAY['a11y-formularios', 'seguridad-credenciales']::TEXT[], $webwiz5${"id":"rev-04","type":"review","title":"Formulario de acceso con \"recordarme\"","description":"Nuevo login: email, contraseña, recordar sesión y botón de entrar. Guardamos el token para no pedir login otra vez.","file":"src/login.html","language":"html","difficulty":"junior","diff":"+<form id=\"login\" novalidate>\n+  <h1>Iniciar sesión</h1>\n+  <input id=\"email\" type=\"email\" placeholder=\"Email\" autocomplete=\"email\">\n+  <input id=\"password\" type=\"password\" placeholder=\"Contraseña\" autocomplete=\"current-password\">\n+  <label><input id=\"recordar\" type=\"checkbox\"> Recordarme</label>\n+  <div class=\"boton\" onclick=\"entrar()\">Entrar</div>\n+  <p id=\"error\" class=\"error\" hidden></p>\n+</form>\n+\n+<script>\n+  async function entrar() {\n+    const email = document.querySelector(\"#email\").value;\n+    const password = document.querySelector(\"#password\").value;\n+    console.log(\"login\", email, password);\n+    const res = await fetch(\"/api/login\", {\n+      method: \"POST\",\n+      headers: { \"Content-Type\": \"application/json\" },\n+      body: JSON.stringify({ email, password }),\n+    });\n+    if (!res.ok) {\n+      const error = document.querySelector(\"#error\");\n+      error.textContent = \"Email o contraseña incorrectos\";\n+      error.hidden = false;\n+      return;\n+    }\n+    const { token } = await res.json();\n+    if (document.querySelector(\"#recordar\").checked) {\n+      localStorage.setItem(\"token\", token);\n+    }\n+    location.href = \"/panel\";\n+  }\n+</script>","issues":[{"id":"labels","category":"accesibilidad","match":"<input id=\"email\" type=\"email\" placeholder=\"Email\"","span":2,"title":"Campos sin etiqueta (solo placeholder)","explanation":"El placeholder desaparece al escribir y no siempre se anuncia como nombre. Cada campo necesita un <label for> visible.","concepts":["a11y-formularios"]},{"id":"div-button","category":"accesibilidad","match":"<div class=\"boton\" onclick=\"entrar()\">","title":"Botón hecho con un div","explanation":"No es enfocable, no responde a Enter/Espacio y no se anuncia como botón. Usa <button type=\"submit\"> y escucha el evento submit del formulario.","concepts":["a11y-formularios"]},{"id":"log","category":"seguridad","match":"console.log(\"login\", email, password);","title":"La contraseña se escribe en la consola","explanation":"Los logs acaban en extensiones, herramientas de sesión grabada o capturas de soporte. Nunca registres credenciales.","concepts":["seguridad-credenciales"]}]}$webwiz5$::jsonb, false),
  ('rev-05', 'Endpoint de pedidos con sus productos', 'GET /api/pedidos?cliente=… devuelve los pedidos de un cliente con sus líneas de producto.', 'revisiones', 'review', 'senior', ARRAY['sql-inyeccion', 'sql-rendimiento', 'promises']::TEXT[], $webwiz5${"id":"rev-05","type":"review","title":"Endpoint de pedidos con sus productos","description":"GET /api/pedidos?cliente=… devuelve los pedidos de un cliente con sus líneas de producto.","file":"server/routes/pedidos.js","language":"javascript","difficulty":"senior","diff":" import { Router } from \"express\";\n import { db } from \"../db.js\";\n \n+export const pedidos = Router();\n+\n+pedidos.get(\"/api/pedidos\", async (req, res) => {\n+  const cliente = req.query.cliente;\n+  if (!cliente) return res.status(400).json({ error: \"Falta el cliente\" });\n+\n+  const filas = await db.query(\n+    \"SELECT id, fecha, total FROM pedidos WHERE cliente = '\" + cliente + \"' ORDER BY fecha DESC\"\n+  );\n+\n+  const resultado = [];\n+  for (const pedido of filas.rows) {\n+    const lineas = await db.query(\n+      \"SELECT producto, cantidad, precio FROM lineas WHERE pedido_id = $1\",\n+      [pedido.id]\n+    );\n+    resultado.push({ ...pedido, lineas: lineas.rows });\n+  }\n+\n+  res.json(resultado);\n+});\n+\n+pedidos.delete(\"/api/pedidos/:id\", async (req, res) => {\n+  const borrado = db.query(\"DELETE FROM pedidos WHERE id = $1 AND cliente = $2\", [\n+    req.params.id,\n+    req.user.cliente,\n+  ]);\n+  if (borrado.rowCount === 0) return res.status(404).end();\n+  res.status(204).end();\n+});","issues":[{"id":"sqli","category":"seguridad","match":"\"SELECT id, fecha, total FROM pedidos WHERE cliente = '\" + cliente","title":"Inyección SQL","explanation":"El parámetro de la URL se concatena en la consulta: ?cliente=' OR '1'='1 devuelve todos los pedidos. Usa parámetros ($1) como en la consulta de líneas.","concepts":["sql-inyeccion"]},{"id":"n1","category":"rendimiento","match":"  for (const pedido of filas.rows) {","span":6,"title":"Consultas N+1","explanation":"Una consulta por pedido: con 200 pedidos son 201 viajes a la base de datos. Trae todas las líneas de una vez (WHERE pedido_id = ANY($1)) o con un JOIN y agrúpalas en memoria.","concepts":["sql-rendimiento"]},{"id":"await","category":"bug","match":"  const borrado = db.query(\"DELETE","title":"Falta await en el DELETE","explanation":"db.query devuelve una promesa: borrado.rowCount es undefined, nunca es 0, y los errores de la consulta quedan sin capturar. Falta await.","concepts":["promises"]}]}$webwiz5$::jsonb, false),
  ('rev-06', 'Utilidades de paginación y etiquetas', 'Helpers para paginar la tabla de usuarios y marcar los que tienen etiquetas destacadas.', 'revisiones', 'review', 'semi_senior', ARRAY['array-methods', 'references']::TEXT[], $webwiz5${"id":"rev-06","type":"review","title":"Utilidades de paginación y etiquetas","description":"Helpers para paginar la tabla de usuarios y marcar los que tienen etiquetas destacadas.","file":"src/utils/tabla.ts","language":"typescript","difficulty":"semi_senior","diff":"+export type Usuario = { id: string; nombre: string; etiquetas: string[]; alta: string };\n+\n+/** Página n (empieza en 1) de tamaño \"porPagina\". */\n+export function pagina<T>(items: T[], n: number, porPagina = 20): T[] {\n+  const inicio = n * porPagina;\n+  return items.slice(inicio, inicio + porPagina);\n+}\n+\n+export function totalPaginas(total: number, porPagina = 20): number {\n+  return Math.ceil(total / porPagina);\n+}\n+\n+/** Marca los usuarios que tienen alguna etiqueta destacada. */\n+export function destacados(usuarios: Usuario[], etiquetas: string[]): Usuario[] {\n+  return usuarios.filter((u) => u.etiquetas.some((e) => etiquetas.includes(e)));\n+}\n+\n+/** Usuarios dados de alta después de \"desde\" (YYYY-MM-DD). */\n+export function altasDesde(usuarios: Usuario[], desde: string): Usuario[] {\n+  return usuarios.filter((u) => new Date(u.alta) > new Date(desde));\n+}\n+\n+/** Ordena por nombre respetando tildes. */\n+export function ordenar(usuarios: Usuario[]): Usuario[] {\n+  return usuarios.sort((a, b) => a.nombre.localeCompare(b.nombre, \"es\"));\n+}\n+\n+/** Busca por nombre sin distinguir mayúsculas ni tildes. */\n+export function buscar(usuarios: Usuario[], texto: string): Usuario[] {\n+  const norm = (s: string) => s.normalize(\"NFD\").replace(/[̀-ͯ]/g, \"\").toLowerCase();\n+  const q = norm(texto.trim());\n+  return q ? usuarios.filter((u) => norm(u.nombre).includes(q)) : usuarios;\n+}\n+\n+/** Texto del pie de la tabla: \"Mostrando 21-40 de 95\". */\n+export function pie(n: number, total: number, porPagina = 20): string {\n+  const desde = (n - 1) * porPagina + 1;\n+  return `Mostrando ${desde}-${Math.min(n * porPagina, total)} de ${total}`;\n+}","issues":[{"id":"offbyone","category":"bug","match":"  const inicio = n * porPagina;","title":"Error de uno en la paginación","explanation":"Si las páginas empiezan en 1, la primera debe empezar en 0: (n - 1) * porPagina. Ahora la página 1 se salta los primeros 20 usuarios.","concepts":["array-methods"]},{"id":"set","category":"rendimiento","match":"u.etiquetas.some((e) => etiquetas.includes(e))","title":"Búsqueda cuadrática con includes","explanation":"includes recorre el array de etiquetas en cada comprobación: O(usuarios × etiquetas × destacadas). Crea un Set antes del filter y usa set.has(e).","concepts":["array-methods"]},{"id":"mutate","category":"bug","match":"  return usuarios.sort(","title":"sort muta el array recibido","explanation":"sort ordena en el sitio: el array original del estado cambia sin que nadie lo sepa (en React, render con datos mutados). Usa [...usuarios].sort(...) o toSorted().","concepts":["references"]}]}$webwiz5$::jsonb, false),
  ('rev-07', 'Lista de tareas reordenable con modal de borrado', 'Lista de tareas con flechas para reordenar y un modal de confirmación antes de borrar.', 'revisiones', 'review', 'senior', ARRAY['react-listas', 'array-methods', 'a11y-dialogos']::TEXT[], $webwiz5${"id":"rev-07","type":"review","title":"Lista de tareas reordenable con modal de borrado","description":"Lista de tareas con flechas para reordenar y un modal de confirmación antes de borrar.","file":"src/components/Tareas.tsx","language":"tsx","difficulty":"senior","diff":" import { useState } from \"react\";\n \n+type Tarea = { id: string; texto: string; hecha: boolean; prioridad: number };\n+\n+export function Tareas({ tareas, onCambio }: { tareas: Tarea[]; onCambio: (t: Tarea[]) => void }) {\n+  const [borrando, setBorrando] = useState<Tarea | null>(null);\n+  const ordenadas = [...tareas].sort((a, b) => b.prioridad - a.prioridad || a.texto.localeCompare(b.texto));\n+\n+  const mover = (i: number, delta: number) => {\n+    const copia = [...ordenadas];\n+    [copia[i], copia[i + delta]] = [copia[i + delta], copia[i]];\n+    onCambio(copia.map((t, j) => ({ ...t, prioridad: copia.length - j })));\n+  };\n+\n+  return (\n+    <>\n+      <ul>\n+        {ordenadas.map((t, i) => (\n+          <li key={i}>\n+            <input type=\"checkbox\" defaultChecked={t.hecha} aria-label={t.texto} />\n+            {t.texto}\n+            <button onClick={() => mover(i, -1)} aria-label=\"Subir\">↑</button>\n+            <button onClick={() => mover(i, 1)} aria-label=\"Bajar\">↓</button>\n+            <button onClick={() => setBorrando(t)}>Borrar</button>\n+          </li>\n+        ))}\n+      </ul>\n+      {borrando && (\n+        <div className=\"modal\">\n+          <p>¿Borrar «{borrando.texto}»?</p>\n+          <button onClick={() => onCambio(tareas.filter((t) => t.id !== borrando.id))}>Sí</button>\n+          <button onClick={() => setBorrando(null)}>No</button>\n+        </div>\n+      )}\n+    </>\n+  );\n+}","issues":[{"id":"key","category":"bug","match":"          <li key={i}>","title":"key con el índice en una lista reordenable","explanation":"Al mover una tarea, React reutiliza el <li> por posición: el checkbox no controlado (defaultChecked) se queda en su sitio y marca la tarea equivocada. Usa key={t.id}.","concepts":["react-listas"]},{"id":"bounds","category":"bug","match":"    [copia[i], copia[i + delta]] = [copia[i + delta], copia[i]];","title":"Sin límites al mover","explanation":"Subir la primera o bajar la última intercambia con undefined: la tarea desaparece de la lista. Comprueba que i + delta esté dentro del array (o desactiva el botón).","concepts":["array-methods"]},{"id":"modal","category":"accesibilidad","match":"        <div className=\"modal\">","span":2,"title":"Modal sin semántica ni foco","explanation":"Falta role=\"dialog\" (o <dialog>), aria-modal, un título asociado y mover el foco al abrir; Escape no cierra. Con <dialog> y showModal() lo tienes casi todo.","concepts":["a11y-dialogos"]}]}$webwiz5$::jsonb, false),
  ('rev-08', 'Buscador con autocompletado', 'Autocompletado de productos con debounce de 300 ms para no saturar la API.', 'revisiones', 'review', 'semi_senior', ARRAY['seguridad-eval', 'closures', 'promises', 'event-loop']::TEXT[], $webwiz5${"id":"rev-08","type":"review","title":"Buscador con autocompletado","description":"Autocompletado de productos con debounce de 300 ms para no saturar la API.","file":"src/buscador.js","language":"javascript","difficulty":"semi_senior","diff":"+const input = document.querySelector(\"#buscar\");\n+const sugerencias = document.querySelector(\"#sugerencias\");\n+\n+function debounce(fn, ms) {\n+  let t;\n+  return (...args) => {\n+    clearTimeout(t);\n+    t = setTimeout(() => fn(...args), ms);\n+  };\n+}\n+\n+async function buscar(q) {\n+  if (q.length < 2) {\n+    sugerencias.replaceChildren();\n+    return;\n+  }\n+  const res = await fetch(\"/api/productos?q=\" + encodeURIComponent(q));\n+  const datos = eval(\"(\" + (await res.text()) + \")\");\n+  sugerencias.replaceChildren(\n+    ...datos.map((p) => {\n+      const li = document.createElement(\"li\");\n+      li.textContent = p.nombre;\n+      return li;\n+    })\n+  );\n+}\n+\n+input.addEventListener(\"input\", (e) => {\n+  debounce(buscar, 300)(e.target.value);\n+});","issues":[{"id":"eval","category":"seguridad","match":"const datos = eval(\"(\" + (await res.text()) + \")\");","title":"eval sobre la respuesta del servidor","explanation":"Cualquier cosa que devuelva la API (o un intermediario) se ejecuta como código. Usa res.json().","concepts":["seguridad-eval"]},{"id":"debounce","category":"rendimiento","match":"  debounce(buscar, 300)(e.target.value);","title":"El debounce se crea en cada pulsación","explanation":"Cada evento crea un debounce nuevo con su propio temporizador, así que no cancela el anterior: se hace una petición por tecla. Crea la función una vez fuera del listener.","concepts":["closures"]},{"id":"race","category":"bug","match":"  const res = await fetch(\"/api/productos?q=\" + encodeURIComponent(q));","title":"Respuestas fuera de orden","explanation":"Una búsqueda lenta anterior puede llegar después de la actual y mostrar sugerencias de un texto antiguo. Cancela con AbortController o comprueba que q sigue siendo el valor del input.","concepts":["promises","event-loop"]}]}$webwiz5$::jsonb, false)
INSERT INTO questions (id, question, options, "correctAnswer", category, subcategory, difficulty, "shortExplanation", concepts, kind, code, option_meta)
VALUES
  ('7c2e0b20-0000-4000-8000-000000000001'::uuid, $webwiz5$Explica por qué este bucle imprime 3, 3, 3 y cómo harías que imprima 0, 1, 2.$webwiz5$, '[]'::jsonb, '', 'explicalo', 'closures', 'semi_senior', $webwiz5$Las tres flechas cierran sobre la misma i porque var tiene ámbito de función. Los setTimeout se ejecutan cuando el bucle ya acabó y i vale 3. Con let cada iteración tiene su propia i y se imprime 0, 1, 2.$webwiz5$, ARRAY['closures']::TEXT[], 'explain', $webwiz5$for (var i = 0; i < 3; i++) {
